export const KIND = {"id":74,"example":{"id":"E74","kind":74,"source":"aether","statement":["Write a class `ordered::tree<T>` whose objects are trees in which each node keeps a value of type T and owns a left and a right branch.","Its explicit constructor takes a `const T&` and makes a tree of one node that holds it.","`insert(const T& value)` adds a node for value: from the top node down, it goes to the left branch when value is above the node's value, else to the right, until it reaches an empty branch, where the new node goes.","`value()` returns the node's value; `left()` and `right()` return the branches as `const std::unique_ptr<tree<T>>&`, empty when there is no branch.","`begin()` and `end()` let a range `for` take every value of the tree, largest first.","Limits: 1 ≤ number of values ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <memory>","#include <vector>","","namespace ordered {","","template <typename T>","class tree {","    T value_ {};","    std::unique_ptr<tree> left_ {};","    std::unique_ptr<tree> right_ {};","    std::vector<T> sorted_ {};","public:","    explicit tree(const T& value)","        : value_ {value}","    {","    }","    const T& value() const","    {","        return value_;","    }","    const std::unique_ptr<tree>& left() const","    {","        return left_;","    }","    const std::unique_ptr<tree>& right() const","    {","        return right_;","    }","    void insert(const T& value)","    {","        auto& branch {value > value_ ? left_ : right_};","        if (branch == nullptr) {","            branch = std::make_unique<tree>(value);","        } else {","            branch->insert(value);","        }","    }","    void collect(std::vector<T>& values) const","    {","        if (left_ != nullptr) {","            left_->collect(values);","        }","        values.push_back(value_);","        if (right_ != nullptr) {","            right_->collect(values);","        }","    }","    auto begin()","    {","        sorted_.clear();","        collect(sorted_);","        return sorted_.cbegin();","    }","    auto end() const","    {","        return sorted_.cend();","    }","};","","}  // namespace ordered"],"frame":[0,2,3,5,59,61],"labels":[{"at":2,"level":0,"text":"Include `memory`, the part of the library that holds `std::unique_ptr`."},{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":10,"level":0,"text":"Hold a branch in a `std::unique_ptr`, which owns the object it points to and starts empty."},{"at":14,"level":1,"text":"Write a constructor that sets the data."},{"at":18,"level":1,"text":"Write member functions that give back the data."},{"at":30,"level":1,"text":"Write a member function that solves its task by calling itself on a smaller part."},{"at":32,"level":2,"text":"Pick the left branch for a value above the data, else the right."},{"at":32,"level":0,"text":"Name a variable for another with `auto&`, and pick one of 2 values with `?` and `:`, the first when the test holds."},{"at":33,"level":2,"text":"Put a new tree there when the branch is empty, else insert into the branch."},{"at":33,"level":0,"text":"Test whether a pointer is empty with `== nullptr`."},{"at":34,"level":0,"text":"Make a new object that a `std::unique_ptr` owns with `std::make_unique`."},{"at":36,"level":0,"text":"Call a member function through a pointer with `->`."},{"at":39,"level":1,"text":"Write a member function that solves its task by calling itself on a smaller part."},{"at":39,"level":0,"text":"Give the function a `std::vector<T>&` parameter, with no `const`, so it changes the caller's list."},{"at":41,"level":2,"text":"Add the left branch's values, then the data, then the right branch's values."},{"at":49,"level":1,"text":"Write member functions that give back the start and the end of the values in order."},{"at":49,"level":0,"text":"Write `auto` as the type of the answer, so the compiler works it out from the `return`."},{"at":51,"level":2,"text":"Fill the list with the values in order, then give back its start."},{"at":53,"level":0,"text":"Give back where a list starts and ends with `cbegin()` and `cend()`, so a range `for` can take each value."}],"blanks":[]}},"trace":{"id":"T74","lines":["#include <iostream>","#include <print>","","int digit_sum(int number)","{","    if (number < 10) {","        return number;","    }","    return number % 10 + digit_sum(number / 10);","}","","int main()","{","    int number {0};","    std::cin >> number;","    std::println(\"{}\", digit_sum(number));","}"],"columns":["number"],"inputs":["47\n","9035\n"],"rows":[{"line":14,"values":["0"]},{"line":15,"values":["47"]},{"line":6,"values":["47"]},{"line":6,"values":["4"]},{"line":7,"values":["4"]},{"line":9,"values":["47"]},{"line":16,"values":["47"]}],"output":"17\n"},"traces":[],"problems":{"74.01":{"id":"74.01","kind":74,"source":"exercism","statement":["Write a class `binary_search_tree::binary_tree<T>` whose objects are trees in which each node keeps a value of type T and owns a left and a right branch.","Its explicit constructor takes a `const T&` and makes a tree of one node that holds it.","`insert(const T& value)` adds a node for value: from the top node down, it goes to the left branch when value is not above the node's value, else to the right, until it reaches an empty branch, where the new node goes.","`data()` returns the node's value; `left()` and `right()` return the branches as `const std::unique_ptr<binary_tree<T>>&`, empty when there is no branch.","`begin()` and `end()` let a range `for` take every value of the tree in ascending order.","Limits: none"],"examples":[{"input":"data_is_retained","output":""}],"tests":[{"input":"smaller_number_at_left_node","output":""},{"input":"same_number_at_left_node","output":""},{"input":"greater_number_at_right_node","output":""},{"input":"can_create_complex_tree","output":""},{"input":"can_sort_single_number","output":""},{"input":"can_sort_if_second_number_is_smaller_than_first","output":""},{"input":"can_sort_if_second_number_is_same_as_first","output":""},{"input":"can_sort_if_second_number_is_greater_than_first","output":""},{"input":"can_sort_complex_tree","output":""},{"input":"can_create_complex_tree_strings","output":""},{"input":"can_sort_complex_tree_strings","output":""}],"solution":{"lines":["#pragma once","","#include <cstdint>","#include <memory>","#include <vector>","","namespace binary_search_tree {","","template <typename T>","class binary_tree {","    T data_ {};","    std::unique_ptr<binary_tree> left_ {};","    std::unique_ptr<binary_tree> right_ {};","    std::vector<T> sorted_ {};","public:","    explicit binary_tree(const T& data)","        : data_ {data}","    {","    }","    const T& data() const","    {","        return data_;","    }","    const std::unique_ptr<binary_tree>& left() const","    {","        return left_;","    }","    const std::unique_ptr<binary_tree>& right() const","    {","        return right_;","    }","    void insert(const T& value)","    {","        auto& branch {value <= data_ ? left_ : right_};","        if (branch == nullptr) {","            branch = std::make_unique<binary_tree>(value);","        } else {","            branch->insert(value);","        }","    }","    void collect(std::vector<T>& values) const","    {","        if (left_ != nullptr) {","            left_->collect(values);","        }","        values.push_back(data_);","        if (right_ != nullptr) {","            right_->collect(values);","        }","    }","    auto begin()","    {","        sorted_.clear();","        collect(sorted_);","        return sorted_.cbegin();","    }","    auto end() const","    {","        return sorted_.cend();","    }","};","","}  // namespace binary_search_tree"],"frame":[0,2,3,4,6,60,62],"labels":[{"at":8,"level":1,"text":"Write a class that keeps its data in private members."},{"at":15,"level":1,"text":"Write a constructor that sets the data."},{"at":19,"level":1,"text":"Write member functions that give back the data."},{"at":31,"level":1,"text":"Write a member function that solves its task by calling itself on a smaller part."},{"at":33,"level":2,"text":"Pick the left branch for a value not above the data, else the right."},{"at":34,"level":2,"text":"Put a new tree there when the branch is empty, else insert into the branch."},{"at":40,"level":1,"text":"Write a member function that solves its task by calling itself on a smaller part."},{"at":42,"level":2,"text":"Add the left branch's values, then the data, then the right branch's values."},{"at":50,"level":1,"text":"Write member functions that give back the start and the end of the values in order."},{"at":52,"level":2,"text":"Fill the list with the values in order, then give back its start."}],"blanks":[{"line":11,"from":39,"to":41},{"line":15,"from":25,"to":38},{"line":21,"from":15,"to":20},{"line":31,"from":16,"to":30},{"line":33,"from":22,"to":36},{"line":34,"from":12,"to":29},{"line":40,"from":17,"to":39},{"line":45,"from":25,"to":30},{"line":54,"from":15,"to":31},{"line":58,"from":15,"to":29}]},"fn":{"slug":"binary-search-tree","commit":"8d139cb0","header":"binary_search_tree.h","name":"binary_search_tree_test.cpp","test":"#include \"binary_search_tree.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <vector>\n\n// test data version: 1.0.0\n\ntemplate <typename T>\nusing tree_ptr = typename std::unique_ptr<binary_search_tree::binary_tree<T>>;\n\ntemplate <typename T>\nstatic void test_leaf(const tree_ptr<T> &tree, const T &data, bool has_left,\n                      bool has_right) {\n    REQUIRE(data == tree->data());\n    REQUIRE((bool)tree->left() == has_left);\n    REQUIRE((bool)tree->right() == has_right);\n}\n\ntemplate <typename T>\nstatic tree_ptr<T> make_tree(const std::vector<T> &data) {\n    if (data.empty()) return tree_ptr<T>(nullptr);\n\n    auto data_iter = data.begin();\n    auto tree = tree_ptr<T>(new binary_search_tree::binary_tree<T>(*data_iter));\n    ++data_iter;\n\n    for (; data_iter != data.end(); ++data_iter) {\n        tree->insert(*data_iter);\n    }\n\n    return tree;\n}\n\nTEST_CASE(\"data_is_retained\") {\n    auto tested = make_tree<uint32_t>({4});\n    test_leaf<uint32_t>(tested, 4, false, false);\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"smaller_number_at_left_node\") {\n    auto tested = make_tree<uint32_t>({4, 2});\n\n    test_leaf<uint32_t>(tested, 4, true, false);\n    test_leaf<uint32_t>(tested->left(), 2, false, false);\n}\n\nTEST_CASE(\"same_number_at_left_node\") {\n    auto tested = make_tree<uint32_t>({4, 4});\n\n    test_leaf<uint32_t>(tested, 4, true, false);\n    test_leaf<uint32_t>(tested->left(), 4, false, false);\n}\n\nTEST_CASE(\"greater_number_at_right_node\") {\n    auto tested = make_tree<uint32_t>({4, 5});\n\n    test_leaf<uint32_t>(tested, 4, false, true);\n    test_leaf<uint32_t>(tested->right(), 5, false, false);\n}\n\nTEST_CASE(\"can_create_complex_tree\") {\n    auto tested = make_tree<uint32_t>({4, 2, 6, 1, 3, 5, 7});\n\n    test_leaf<uint32_t>(tested, 4, true, true);\n    test_leaf<uint32_t>(tested->left(), 2, true, true);\n    test_leaf<uint32_t>(tested->right(), 6, true, true);\n\n    test_leaf<uint32_t>(tested->left()->left(), 1, false, false);\n    test_leaf<uint32_t>(tested->left()->right(), 3, false, false);\n\n    test_leaf<uint32_t>(tested->right()->left(), 5, false, false);\n    test_leaf<uint32_t>(tested->right()->right(), 7, false, false);\n}\n\n// The tests below require an implementation of an iterator.\n// You can get more details here: http://www.cplusplus.com/reference/iterator/\n\ntemplate <typename T>\nstatic void test_sort(const tree_ptr<T> &tree, const std::vector<T> &expected) {\n    std::vector<T> actual;\n    for (auto &x : *tree) {\n        actual.push_back(x);\n    }\n    REQUIRE(expected == actual);\n}\n\nTEST_CASE(\"can_sort_single_number\") {\n    test_sort(make_tree<uint32_t>({2}), {2});\n}\n\nTEST_CASE(\"can_sort_if_second_number_is_smaller_than_first\") {\n    test_sort(make_tree<uint32_t>({2, 1}), {1, 2});\n}\n\nTEST_CASE(\"can_sort_if_second_number_is_same_as_first\") {\n    test_sort(make_tree<uint32_t>({2, 2}), {2, 2});\n}\n\nTEST_CASE(\"can_sort_if_second_number_is_greater_than_first\") {\n    test_sort(make_tree<uint32_t>({2, 3}), {2, 3});\n}\n\nTEST_CASE(\"can_sort_complex_tree\") {\n    test_sort(make_tree<uint32_t>({2, 1, 3, 6, 7, 5}), {1, 2, 3, 5, 6, 7});\n}\n\n// strings\n\nTEST_CASE(\"can_create_complex_tree_strings\") {\n    auto tested = make_tree<std::string>(\n        {\"delicious\", \"ballon\", \"flag\", \"apple\", \"cat\", \"elispsis\", \"grains\"});\n\n    test_leaf<std::string>(tested, \"delicious\", true, true);\n    test_leaf<std::string>(tested->left(), \"ballon\", true, true);\n    test_leaf<std::string>(tested->right(), \"flag\", true, true);\n\n    test_leaf<std::string>(tested->left()->left(), \"apple\", false, false);\n    test_leaf<std::string>(tested->left()->right(), \"cat\", false, false);\n\n    test_leaf<std::string>(tested->right()->left(), \"elispsis\", false, false);\n    test_leaf<std::string>(tested->right()->right(), \"grains\", false, false);\n}\n\nTEST_CASE(\"can_sort_complex_tree_strings\") {\n    test_sort(\n        make_tree<std::string>({\"A\", \"few\", \"random\", \"strings\", \"that\",\n                                \"should\", \"be\", \"sorted\"}),\n        {\"A\", \"be\", \"few\", \"random\", \"should\", \"sorted\", \"strings\", \"that\"});\n}\n\n#endif\n","setup":["auto tested = make_tree<uint32_t>({4});","test_leaf<uint32_t>(tested, 4, false, false);"],"calls":[]}},"74.02":{"id":"74.02","kind":74,"source":"aether","statement":["Write a class `word_tree::tree` whose objects are trees in which each node keeps a word, a `std::string`, and owns a left and a right branch.","Its explicit constructor takes a `const std::string&` and makes a tree of one node that holds it.","`insert(const std::string& word)` adds a node for the word: from the top node down, it goes to the left branch when the word is shorter than the node's word, else to the right, until it reaches an empty branch, where the new node goes.","`word()` returns the node's word; `before()` and `after()` return the left and the right branch as `const std::unique_ptr<tree>&`, empty when there is no branch.","`begin()` and `end()` let a range `for` take every word of the tree from shortest to longest, words of the same length in the order they were added.","Limits: 1 ≤ number of words ≤ 1000; 0 ≤ length of each word ≤ 20."],"examples":[{"input":"shortest_first","output":""}],"tests":[{"input":"one_word","output":""},{"input":"shorter_goes_left","output":""},{"input":"same_length_goes_right","output":""},{"input":"longer_goes_right","output":""},{"input":"same_length_in_order_added","output":""},{"input":"empty_word","output":""},{"input":"largest","output":""}],"solution":{"lines":["#pragma once","","#include <memory>","#include <string>","#include <vector>","","namespace word_tree {","","class tree {","    std::string word_ {};","    std::unique_ptr<tree> before_ {};","    std::unique_ptr<tree> after_ {};","    std::vector<std::string> sorted_ {};","public:","    explicit tree(const std::string& word)","        : word_ {word}","    {","    }","    const std::string& word() const","    {","        return word_;","    }","    const std::unique_ptr<tree>& before() const","    {","        return before_;","    }","    const std::unique_ptr<tree>& after() const","    {","        return after_;","    }","    void insert(const std::string& word)","    {","        auto& branch {","            word.size() < word_.size() ? before_ : after_};","        if (branch == nullptr) {","            branch = std::make_unique<tree>(word);","        } else {","            branch->insert(word);","        }","    }","    void collect(std::vector<std::string>& words) const","    {","        if (before_ != nullptr) {","            before_->collect(words);","        }","        words.push_back(word_);","        if (after_ != nullptr) {","            after_->collect(words);","        }","    }","    auto begin()","    {","        sorted_.clear();","        collect(sorted_);","        return sorted_.cbegin();","    }","    auto end() const","    {","        return sorted_.cend();","    }","};","","}  // namespace word_tree"],"frame":[0,2,3,4,6,60,62],"labels":[{"at":8,"level":1,"text":"Write a class that keeps its data in private members."},{"at":14,"level":1,"text":"Write a constructor that sets the data."},{"at":18,"level":1,"text":"Write member functions that give back the data."},{"at":30,"level":1,"text":"Write a member function that solves its task by calling itself on a smaller part."},{"at":32,"level":2,"text":"Pick the left branch for a shorter word, else the right."},{"at":34,"level":2,"text":"Put a new tree there when the branch is empty, else insert into the branch."},{"at":40,"level":1,"text":"Write a member function that solves its task by calling itself on a smaller part."},{"at":42,"level":2,"text":"Add the left branch's values, then the data, then the right branch's values."},{"at":50,"level":1,"text":"Write member functions that give back the start and the end of the values in order."},{"at":52,"level":2,"text":"Fill the list with the values in order, then give back its start."}],"blanks":[{"line":10,"from":34,"to":36},{"line":15,"from":17,"to":21},{"line":20,"from":15,"to":20},{"line":30,"from":16,"to":39},{"line":33,"from":12,"to":38},{"line":34,"from":12,"to":29},{"line":40,"from":17,"to":48},{"line":45,"from":24,"to":29},{"line":54,"from":15,"to":31},{"line":58,"from":15,"to":29}]},"fn":{"slug":"word_tree","commit":"","header":"word_tree.h","name":"word_tree_test.cpp","test":"#include \"word_tree.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"shortest_first\") {\n    word_tree::tree words {\"pear\"};\n    words.insert(\"fig\");\n    words.insert(\"banana\");\n    std::vector<std::string> order {};\n    for (const std::string& word : words) {\n        order.push_back(word);\n    }\n    REQUIRE(order == std::vector<std::string> {\"fig\", \"pear\", \"banana\"});\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"one_word\") {\n    word_tree::tree words {\"kiwi\"};\n    REQUIRE(words.word() == \"kiwi\");\n    REQUIRE(words.before() == nullptr);\n    REQUIRE(words.after() == nullptr);\n    std::vector<std::string> order {};\n    for (const std::string& word : words) {\n        order.push_back(word);\n    }\n    REQUIRE(order == std::vector<std::string> {\"kiwi\"});\n}\nTEST_CASE(\"shorter_goes_left\") {\n    word_tree::tree words {\"apple\"};\n    words.insert(\"ox\");\n    REQUIRE(words.before() != nullptr);\n    REQUIRE(words.before()->word() == \"ox\");\n    REQUIRE(words.after() == nullptr);\n}\nTEST_CASE(\"same_length_goes_right\") {\n    word_tree::tree words {\"cat\"};\n    words.insert(\"dog\");\n    REQUIRE(words.before() == nullptr);\n    REQUIRE(words.after()->word() == \"dog\");\n}\nTEST_CASE(\"longer_goes_right\") {\n    word_tree::tree words {\"cat\"};\n    words.insert(\"horse\");\n    words.insert(\"zebra\");\n    REQUIRE(words.after()->word() == \"horse\");\n    REQUIRE(words.after()->after()->word() == \"zebra\");\n}\nTEST_CASE(\"same_length_in_order_added\") {\n    word_tree::tree words {\"bb\"};\n    words.insert(\"aa\");\n    words.insert(\"c\");\n    words.insert(\"dd\");\n    words.insert(\"e\");\n    std::vector<std::string> order {};\n    for (const std::string& word : words) {\n        order.push_back(word);\n    }\n    REQUIRE(order\n            == std::vector<std::string> {\"c\", \"e\", \"bb\", \"aa\", \"dd\"});\n}\nTEST_CASE(\"empty_word\") {\n    word_tree::tree words {\"a\"};\n    words.insert(\"\");\n    std::vector<std::string> order {};\n    for (const std::string& word : words) {\n        order.push_back(word);\n    }\n    REQUIRE(order == std::vector<std::string> {\"\", \"a\"});\n}\nTEST_CASE(\"largest\") {\n    word_tree::tree words {std::string(10, 'm')};\n    for (int i {1}; i < 1000; ++i) {\n        words.insert(std::string(static_cast<std::size_t>(i % 21), 'x'));\n    }\n    std::vector<std::string> order {};\n    for (const std::string& word : words) {\n        order.push_back(word);\n    }\n    REQUIRE(order.size() == 1000);\n    REQUIRE(order.front().empty());\n    REQUIRE(order.back() == std::string(20, 'x'));\n    REQUIRE(order[479] == std::string(10, 'm'));\n}\n#endif\n","setup":["word_tree::tree words {\"pear\"};","words.insert(\"fig\");","words.insert(\"banana\");","std::vector<std::string> order {};","for (const std::string& word : words) { order.push_back(word); }"],"calls":[{"call":"order","expected":"std::vector<std::string> {\"fig\", \"pear\", \"banana\"}"}]}}}}
